{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Ranitidine showed 88 ± 10% systemic availability after a 20 mg oral dose versus IV in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Nevirapine had an absolute oral bioavailability of 91 ± 8% in healthy volunteers relative to IV infusion, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tivantinib is reported to have an oral bioavailability of ≥20%, meeting the F ≥ 20% threshold for high.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules support high oral bioavailability at the F ≥ 20% threshold, with numeric absolute values including ranitidine 88%, didanosine ~43%, thalidomide 80–100%, nevirapine 91%, and tivantinib ≥20%; no affirmative threshold-relevant evidence supports low.",
  "evidence_gaps": [
    "Tivantinib is reported only as ≥20%, so the exact margin above the threshold is not specified.",
    "One didanosine pediatric record reports 19%, but it is an altered condition and is outweighed by adult absolute bioavailability values near 43%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

